//go:build linux || freebsd || openbsd || netbsd || dragonfly

package unixauth

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestVerifyRealHashes locks the crypt verification against hashes generated by
// the systems themselves — openssl passwd and mkpasswd, the tools that write
// /etc/shadow — so a change to the dispatch or the underlying libraries cannot
// start accepting a wrong password or rejecting a right one unnoticed. Every
// vector is for the password "test123"; the wrong-password row proves the check
// actually discriminates rather than always passing.
//
// Provenance of the vectors (all "test123"):
//
//	$6$        openssl passwd -6 -salt abcdefgh
//	$6$rounds= mkpasswd -m sha-512 -R 5000 -S abcdefgh
//	$5$        openssl passwd -5 -salt abcdefgh
//	$1$        openssl passwd -1 -salt abcdefgh
//	$y$        mkpasswd -m yescrypt (Arch, the current default scheme)
func TestVerifyRealHashes(t *testing.T) {
	const pw = "test123"
	hashes := map[string]string{
		"sha512crypt":        "$6$abcdefgh$mtjCt3Dh9vsZV8JiCKbrAmn4w.xuVaeKtguTye7a4EiGXmK6HTzDQ3ZLMvOaMwv.tv9uFI989420oTf92V2/V/",
		"sha512crypt rounds": "$6$rounds=5000$abcdefgh$mtjCt3Dh9vsZV8JiCKbrAmn4w.xuVaeKtguTye7a4EiGXmK6HTzDQ3ZLMvOaMwv.tv9uFI989420oTf92V2/V/",
		"sha256crypt":        "$5$abcdefgh$pLnwisw5uVOlso3ziEwUgurjC0sQ8SADkf.lNLKyV/5",
		"md5crypt":           "$1$abcdefgh$FuRpVTqE/Onxax.jDI2aR/",
		"yescrypt":           "$y$j9T$abcdefghijklmnop$EMVSVL9hWIvZMIojNrI2UdKyNgD8uza6SVtB/339/wD",
		// bcrypt is the OpenBSD master.passwd default; generated with
		// golang.org/x/crypto/bcrypt at cost 10.
		"bcrypt": "$2a$10$boZ.1hQRWWauYKD7hrd.8uEM2DauhYa1EAlt46fqKbtI4eQd8V35m",
	}

	for name, hash := range hashes {
		ok, err := Verify(pw, hash)
		require.NoError(t, err, "%s: right password must verify without error", name)
		assert.True(t, ok, "%s: the correct password must match", name)

		ok, err = Verify("wrongpassword", hash)
		require.NoError(t, err, "%s: a wrong password is a false, not an error", name)
		assert.False(t, ok, "%s: a wrong password must not match", name)
	}
}

// TestVerifyRejectsUnverifiableAccounts pins that a locked or password-less
// account is refused with the distinct error, never treated as a wrong
// password and never — for the empty field — silently accepted. This is the
// case that decides whether a credentialed unlock can be tricked into running
// against an account that has no password to check.
func TestVerifyRejectsUnverifiableAccounts(t *testing.T) {
	locked := "$6$abcdefgh$mtjCt3Dh9vsZV8JiCKbrAmn4w.xuVaeKtguTye7a4EiGXmK6HTzDQ3ZLMvOaMwv.tv9uFI989420oTf92V2/V/"
	for _, field := range []string{"", "!", "!!", "*", "x", "!" + locked} {
		ok, err := Verify("test123", field)
		assert.False(t, ok, "field %q must not authenticate", field)
		assert.ErrorIs(t, err, ErrNoPasswordLogin, "field %q must report no password login", field)
	}
}

// TestVerifyUnknownSchemeErrors pins that a hash whose scheme the crypt library
// does not recognise surfaces an error rather than a bare false, so an account
// whose password field is not a supported crypt hash — an LDAP-style token, a
// scheme added in a future release — is routed to the PAM helper instead of
// being silently read as a wrong password. A parseable-but-non-matching hash of
// a known scheme is a wrong password (false, nil) and is covered above; this is
// the different case where the format itself is unrecognised.
func TestVerifyUnknownSchemeErrors(t *testing.T) {
	for _, h := range []string{"{SSHA}0J2Vo1IPomFuColnumbers", "$unknownscheme$x$y"} {
		ok, err := Verify("test123", h)
		assert.False(t, ok, "an unrecognised hash must not authenticate")
		assert.Error(t, err, "an unrecognised scheme must error so it routes to the PAM helper, not read as wrong")
	}
}

// TestHashForUser reads a fixture shaped exactly like /etc/shadow, so the field
// split is exercised without root or a real shadow file. The fixture carries a
// colon inside a later field to prove only the second field is taken as the
// hash.
func TestHashForUser(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "shadow")
	const content = "root:$6$rootsalt$roothash:19000:0:99999:7:::\n" +
		"alice:$y$j9T$abcdefghijklmnop$EMVSVL9hWIvZMIojNrI2UdKyNgD8uza6SVtB/339/wD:19700:0:99999:7:::\n" +
		"bob:!:19700:0:99999:7:::\n"
	require.NoError(t, os.WriteFile(path, []byte(content), 0o600))

	old := passwdFile
	passwdFile = path
	t.Cleanup(func() { passwdFile = old })

	got, err := HashForUser("alice")
	require.NoError(t, err)
	assert.Equal(t, "$y$j9T$abcdefghijklmnop$EMVSVL9hWIvZMIojNrI2UdKyNgD8uza6SVtB/339/wD", got,
		"only the second colon-field is the hash")

	ok, err := VerifyUser("alice", "test123")
	require.NoError(t, err)
	assert.True(t, ok, "the fixture's alice authenticates with her real yescrypt password")

	_, err = HashForUser("carol")
	assert.ErrorIs(t, err, ErrUserNotFound, "a missing user is reported as not found")
}
